CREATE TABLE "AccountPayable" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"description" TEXT NOT NULL,"category" TEXT NOT NULL DEFAULT 'OUTROS',"supplier" TEXT,"amount" DECIMAL(10,2) NOT NULL,"dueDate" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"paidAt" TIMESTAMP(3),"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AccountPayable_pkey" PRIMARY KEY ("id"));CREATE INDEX "AccountPayable_organizationId_status_dueDate_idx" ON "AccountPayable"("organizationId","status","dueDate");ALTER TABLE "AccountPayable" ADD CONSTRAINT "AccountPayable_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;